        cylinder(d=inner_od + 2*race_gap, h=width+0.2, center=true);
        cylinder(d=outer_id - 2*race_gap, h=width+0.2, center=true);
    }

    for(i=[0:ball_count-1]){
        rotate([0,0,360*i/ball_count])
            translate([ball_path_d/2, 0, 0])
                ball(ball_d);
