module motor_can(d, h) {
    cylinder(d=d, h=h, center=true);
}

module stator(d, h) {
    cylinder(d=d, h=h, center=true);
}

module shaft(d, h, z0) {
    translate([0,0,z0]) cylinder(d=d, h=h, center=true);
