module stator_teeth(od, id, h, n, tooth_w, tooth_depth){
    for(i=[0:n-1]){
        a = 360*i/n;
        rotate([0,0,a])
            translate([ (id/2) + tooth_depth/2, 0, 0 ])
                cube([tooth_depth, tooth_w, h], center=true);
