module mounting_base(d, t, bcd, hole_d){
    difference(){
        cylinder(d=d, h=t, center=true);
        translate([0,0,-t/2-0.01])
            bolt_circle_holes(bcd=bcd, hole_d=hole_d, h=t+0.02, n=4, z0=0);
        translate([0,0,-t/2-0.01])
            cylinder(d=8.0, h=t+0.02, center=false);
    }
