    base = ring(od, id, h);
    difference(){
        union(){
            base;
            cylinder(d=hub_od, h=hub_h, center=true);
        }
        for(i=[0:poles-1]){
            if (i % 2 == 0)
                rotate([0,0, i*360/poles])
                    pole_wedge(od, id, h+0.4, depth, 360/poles*0.92);
        }
    }
}

