    translate([xpos,0,0])
    linear_extrude(height=sheet_wid, center=true, convexity=10)
        polygon(points=[
            [-flute_wall/2, -sheet_thk/2 + liner_thk],
            [-flute_wall/2, 0],
            [-flute_wall/2,  sheet_thk/2 - liner_thk],
            [ flute_wall/2,  sheet_thk/2 - liner_thk],
            [ flute_wall/2, 0],
            [ flute_wall/2, -sheet_thk/2 + liner_thk]
